<?php require_once __DIR__.'/../includes/layout.php'; require_once __DIR__.'/../includes/otp.php'; $email=$_SESSION['verify_email']??($_GET['email']??''); $msg=''; if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf(); $email=$_POST['email']; if(verify_otp_code($email,'email_verify',$_POST['otp']??'')){db()->prepare("UPDATE users SET email_verified=1,status='active' WHERE email=?")->execute([$email]); audit('otp_verification','users',null,['email'=>$email]); $msg='Email verified. Your account is active.';} else $msg='Invalid or expired OTP.';} auth_header('Verify Email'); ?><h2 class="brand">Email Verification</h2><p>Enter the 6 digit OTP sent to your email.</p><?php if($msg):?><div class="alert alert-info"><?=e($msg)?></div><?php endif;?><form method="post" class="vstack gap-3"><input type="hidden" name="csrf" value="<?=csrf_token()?>"><input name="email" class="form-control" value="<?=e($email)?>" required><input name="otp" maxlength="6" class="form-control text-center fs-2" placeholder="000000" required><button class="btn btn-premium">Verify OTP</button></form><a href="resend-otp.php?email=<?=urlencode($email)?>">Resend OTP</a><?php auth_footer(); ?>
